update public.settings set value = '{"eyebrow": "Q4 Challenge", "title": "3-Day Arizona Mastermind", "description": "Earn points by learning, building and getting results. The ten members with the most points at the end of Q4 fly out for three days in Arizona with Jakey and the coaching team.", "ends_at": "2026-12-31T23:59:00-05:00", "ends_label": "Challenge ends December 31, 2026 \u00b7 11:59 PM ET", "prizes": [["3 days in Arizona", "In-person mastermind with Jakey and the coaches: builds, pitches and ad accounts, live."], ["Private dinner", "Dinner with Jakey, the coaches and the other nine."], ["Client hand-off", "Jakey''s team hands each winner a warm lead to pitch."]]}'::jsonb where key = 'challenge';
update public.settings set value = '[["Base44", "The AI builder every dashboard, site and agent in the bootcamp runs on. Students and clients both need an account.", "Builder", "https://base44.com", "From $20/mo", "", "base44.com"], ["GoHighLevel", "CRM, pipelines, calendars and invoicing for your clients. White-label it as your own software.", "CRM", "https://www.gohighlevel.com", "From $97/mo", "", "gohighlevel.com"], ["Hyros", "Ad tracking and attribution for clients who run ads. The upsell once campaigns are live.", "Tracking", "https://hyros.com", "From $99/mo", "", "hyros.com"], ["Loom", "Video DMs and client walkthroughs. The outreach channel that gets replies.", "Outreach", "https://www.loom.com", "Free / $15/mo", "", "loom.com"], ["Canva Pro", "Creatives, proposals and client mockups in minutes.", "Creative", "https://www.canva.com", "$15/mo", "", "canva.com"], ["Closing Script SOP", "The exact 20-minute discovery-to-close script Jakey''s team uses, with objection handling. Google Doc, copy it and make it yours.", "Low-ticket", "https://docs.google.com", "$29.99 one time", "", "docs.google.com"], ["Cold Outreach SOP", "DM, email and walk-in scripts by niche, plus the 5-touch follow-up sequence. Google Doc.", "Low-ticket", "https://docs.google.com", "$29.99 one time", "", "docs.google.com"]]'::jsonb where key = 'affiliate_tools';
update public.events set start_time = time '18:00';
insert into public.events (title, coach, description, weekday, start_time, duration_min, color, sort)
select * from (values
  ('Build Session', 'Coach Adriel', 'Live build along: bring your Base44 dashboard, site or agent and finish it on the call.', 2, time '18:00', 60, '#a78bfa', 5),
  ('Sales & Closing', 'Jake', 'Pitch reviews, pricing, objections and live role-plays. Bring a real prospect.', 4, time '18:00', 60, '#ff8a5c', 6)
) as v(title, coach, description, weekday, start_time, duration_min, color, sort)
where not exists (select 1 from public.events where weekday in (2,4));

